"""Individually reviewed sauce formulas; common technique helpers do not select recipes."""
import json,pathlib,sqlite3,copy
root=pathlib.Path(__file__).parent
db=sqlite3.connect(root.parent.parent/'outputs/SavorShelf-Content-Repairs/grouped-work.sqlite3')
def original(id):return json.loads(db.execute('select record from recipes where id=?',(id,)).fetchone()[0])
records={r['sourceId']:r for r in json.loads((root/'content-overrides.json').read_text(encoding='utf-8'))}
aliases={r['id']:r for r in json.loads((root/'recipe-aliases.json').read_text(encoding='utf-8'))}
merges={'historical-ba0f74b7eea36f0f07853623':'historical-5cc3b735b13756a3c7516eaf','historical-27bf69470acc82be7b51c095':'historical-6a05c3d0dac3e602dc21abe4','historical-d130509a26d3c1f6a16a44ec':'historical-6a05c3d0dac3e602dc21abe4','historical-8d7c585590022951e818bcc7':'historical-edac6ffd74d450db40a5738c','historical-50a9d64c368d386fd0fd129f':'historical-068bd35af3417a6ecc7d4800','historical-9eb68b012c5fd0bcb97282c3':'historical-52f41bf29ae0a347f4c4a86a'}
REF='https://dairyfarmersofcanada.ca/en/canadian-goodness/recipes/basic-white-sauce'
EGG='https://www.fda.gov/food/buy-store-serve-safe-food/what-you-need-know-about-egg-safety'
newids=[]
def ing(key,n,unit,name,sub):return dict(key=key,amount=n,unit=unit,name=name,substitution=sub)
def butter(n,key='butter'):return ing(key,n,'g','unsalted butter','Use the same weight of a block-style dairy-free butter alternative; flavor and salt content differ.')
def flour(n):return ing('flour',n,'g','all-purpose wheat flour','Use an equal weight of a gluten-free all-purpose blend intended for sauces; texture can differ. Do not replace with an equal weight of cornstarch.')
def milk(n):return ing('milk',n,'ml','whole milk','Use the same volume of unsweetened soy milk for a dairy-free variation; flavor and thickening may differ.')
def water(n,key='water'):return ing(key,n,'ml','cold drinking water','Unsalted vegetable stock may replace the same volume in a savory sauce, changing its flavor.')
def stock(n):return ing('stock',n,'ml','unsalted light chicken stock','Use the same volume of unsalted vegetable stock for a meat-free variation.')
def cream(n):return ing('cream',n,'ml','heavy cream','Use the same volume of light cream for a less rich sauce; it may be thinner.')
def salt(n):return ing('salt',n,'g','fine salt','Reduce or omit, especially when using salted butter or stock; exchange other salt by weight.')
def pepper(n=.2):return ing('pepper',n,'g','ground white pepper','Use the same weight of black pepper, which leaves visible specks, or omit.')
def sugar(n):return ing('sugar',n,'g','granulated sugar','Omit for a less sweet finish; do not replace with the same weight of concentrated sweetener.')
def lemon(n):return ing('lemon',n,'ml','lemon juice','Use the same volume of lime juice for a different flavor, or omit the acidity.')
def vinegar(n):return ing('vinegar',n,'ml','white wine vinegar','Use the same volume of cider vinegar for a fruitier flavor.')
def nutmeg(n=.1):return ing('nutmeg',n,'g','ground nutmeg','Omit, or use the same small weight of ground mace.')
def yolk():return ing('yolk',1,'','large pasteurized egg yolk','Omit for an egg-free but less rich finish; there is no identical substitute for this liaison.')
def add(id,title,servings,minutes,description,items,steps,notes):
 s=original(id);r=copy.deepcopy(s['recipe']);r.update(title=title,description=description,category='Sauces',servings=servings,yieldUnit='sauce portions',minutes=minutes,totalMinutes=minutes,ingredients=items,steps=steps,sourceStatus='adapted',versionNote='Modern measured adaptation',updatedAt='2026-09-22T12:00:00Z',notes=notes+' Missing or ambiguous source amounts, modern ingredient choices, sauce portions and timings are explicit adaptation estimates, not exact recovered historical measurements. Not kitchen-tested. Serve freshly made; scaling changes quantities, not temperature or cooking time.',source=s['recipe']['source']+' SavorShelf measured adaptation. Roux technique reference: '+REF)
 if any(i['key']=='yolk' for i in items):r['source']+=' Egg cooking guidance: '+EGG
 r['sourceAliases']=[old for old,new in merges.items() if new==id]
 for old in r['sourceAliases']:r['source']+=' Equivalent source retained: '+original(old)['recipe']['source']
 records[id]={'sourceId':id,'bodySha256':s['bodySha256'],'recipe':r};newids.append(id);return r
def roux(id,title,b,f,liquids,n,description,season=(),finish=(),notes='',mode='roux',minutes=15,extra_steps=()):
 items=[butter(b),flour(f),*liquids,*season,*finish]
 l=' and '.join('{{'+x['key']+'}}' for x in liquids)
 if mode=='slurry':
  first=liquids[0]['key'];steps=['Whisk {{flour}} with {{'+first+'|0.25}} in a small saucepan until smooth.','Gradually whisk in the remaining {{'+first+'|0.75}}'+''.join(' and {{'+x['key']+'}}' for x in liquids[1:])+', then add {{butter}} in small pieces.']
 elif mode=='finish-butter':steps=['Melt {{butter|0.5}} in a small heavy saucepan over low heat. Stir in {{flour}} and cook, stirring, for 2 minutes without browning.','Take off the heat and whisk in '+l+' a little at a time until smooth.']
 else:steps=['Melt {{butter}} in a small heavy saucepan over low heat. Stir in {{flour}} and cook, stirring, for 2 minutes without browning.','Take off the heat and whisk in '+l+' a little at a time until smooth.']
 steps+=['Return to medium-low heat, whisking until the sauce gently bubbles. Lower the heat and cook '+('10' if minutes>=20 else '5')+' minutes, stirring along the bottom, until smooth and thickened. Avoid a hard boil.']
 if season:steps+=['Mix in '+', '.join('{{'+i['key']+'}}' for i in season)+'.']
 if mode=='finish-butter':steps+=['Remove from the heat and whisk in the remaining {{butter|0.5}}.']
 if finish:steps+=['Remove from the heat and stir in '+', '.join('{{'+i['key']+'}}' for i in finish)+'. Warm gently if needed, without boiling.']
 steps+=list(extra_steps)+['Serve warm. If too thick after standing, whisk in a small splash of the recipe’s liquid to restore the intended pouring consistency.']
 return add(id,title,n,minutes,description,items,steps,notes)
# Manually reviewed quantities retain the sources' different richness and thickness.
roux('historical-08848a853895b5dcff651cf2','Melted Butter Sauce with Milk',56,7,[milk(30),water(90)],4,'A rich butter sauce uses a little milk and water with flour to give a smooth, lightly thickened finish.',notes='The source butter quantity is about 56 g; its dessertspoon and tablespoons are assigned modern amounts.',mode='slurry')
roux('historical-b145dc6352fdda9a9d8433fb','Melted Butter Sauce — Light Water Base',28,28,[water(500)],8,'A water-based flour sauce is finished with butter, giving a light savory coating without milk.',season=[salt(2)],notes='The truncated method is completed. Half the butter cooks the flour; the remaining half finishes the sauce. Water is a modern 500 ml batch, not an asserted pint conversion.',mode='finish-butter')
r=roux('historical-25aa4710789b90b43cec1a1d','Thin White Sauce — Milk and Butter',28,14,[milk(500)],8,'A thin milk sauce with a small amount of flour lightly coats vegetables or other savory dishes.',season=[salt(2),pepper()],notes='The source’s low flour ratio is retained; the milk volume is a modern 500 ml choice. Its sweet-sauce option is retained as a named variation.')
r['variants']=[{'id':'sweet','label':'Sweet milk sauce','ingredients':[i for i in r['ingredients'] if i['key'] not in ['salt','pepper']]+[sugar(20)],'steps':[s for s in r['steps'][:-1] if '{{salt}}' not in s]+['Stir {{sugar}} into the warm sauce until dissolved. Serve with a dessert.']}]
