roux('historical-2fe49fbb75a1f95a75b6e006','Thick White Stock Sauce with Lemon',21,12,[stock(120)],4,'A small batch of thick white-stock sauce is sharpened with lemon juice at the end.',season=[salt(.5),pepper()],finish=[lemon(15)],notes='The unusually small liquid-to-flour ratio is retained as a thick sauce; the lemon mentioned only in the method is included in the ingredient list.')
r=roux('historical-068bd35af3417a6ecc7d4800','Valkea Kastike (Milk and Cream Sauce)',28,16,[milk(480)],8,'A light milk sauce is enriched with cream for a smooth, gently seasoned finish.',season=[salt(2),pepper()],finish=[cream(120)],notes='Equivalent milk/cream formulations are combined. The later source’s egg-and-lemon finish is retained as a variation; it is not presented as classic hollandaise.')
