r=roux('historical-6a05c3d0dac3e602dc21abe4','Vit Sås (White Sauce with a Butter Finish)',40,40,[milk(700)],12,'A smooth milk sauce is finished off the heat with cold butter, giving a glossy coating for savory dishes.',season=[salt(5),pepper(.5)],finish=[butter(10,'finish')],notes='The source gives gram weights, so those values take precedence over its spoon labels. The mesost variation is retained.')
r['variants']=[{'id':'mesost','label':'Mesost finish for paltbread','ingredients':[i for i in r['ingredients'] if i['key']!='pepper']+[ing('mesost',10,'g','finely grated mesost or brunost','Omit if unavailable; another cheese will change the distinctive sweet whey-cheese flavor.')],'steps':[s.replace(', {{pepper}}','') for s in r['steps'][:-1]]+['Stir {{mesost}} into the warm sauce until melted. Serve without boiling.']}]
