r['variants']=[{'id':'cream','label':'Flourless cream version','ingredients':[butter(113),cream(60),salt(1)],'steps':['Warm {{cream}} in a small saucepan until steaming, without boiling.','Lower the heat and whisk in {{butter}} a few small pieces at a time until smooth. Add {{salt}} and serve at once; do not boil.']}]
