# Cream slurry and vegetable-strained sauces have their own methods.
add('historical-e980a751cf52fd42d52f02a4','White Stock and Cream Sauce',8,20,'Cream and light stock simmer together with a small flour thickener for a rich but pourable sauce.',[stock(250),cream(250),flour(7),salt(1)],['Whisk {{flour}} into {{cream}} until no dry lumps remain.','Heat {{stock}} to a gentle simmer in a heavy saucepan. Whisk in the cream mixture slowly.','Simmer gently for 10 minutes, stirring along the bottom so it does not catch. Add {{salt}} and serve warm.'],'The source uses stock and cream without butter; its gentle ten-minute simmer is retained. Half-pint volumes are modern 250 ml choices.')
add('historical-884192e510e73f269e177ddd','White Sauce with Onion and Carrot',8,30,'Onion and carrot flavor a milk sauce that is strained smooth before serving.',[butter(57),ing('onion',150,'g','peeled onion, finely chopped','Use 150 g shallots for a milder flavor.'),ing('carrot',80,'g','peeled carrot, finely chopped','Use 80 g parsnip for a different, sweeter flavor.'),flour(30),milk(500),salt(2),ing('cayenne',.1,'g','ground cayenne pepper','Omit for a mild sauce.')],['Melt {{butter}} in a saucepan. Add {{onion}} and {{carrot}} and cook over low heat for 8–10 minutes, stirring, until softened without browning.','Stir in {{flour}} and cook for 2 minutes. Gradually whisk in {{milk}} until smooth.','Simmer gently for 10 minutes, stirring often. Press through a fine sieve into a clean pan; discard the remaining vegetable solids.','Mix in {{salt}} and {{cayenne}}. Warm gently and serve.'],'Vegetable and teacup-flour quantities are supplied as modern measured amounts. The vegetable infusion and straining are retained; vegetables are not counted as a separate serving.')
for id,title,f,desc in [('historical-5778d1032c4352a93d8a40af','Thin White Sauce — Boston Formula',12,'A light butter-and-milk sauce has just enough flour to coat gently.'),('historical-0824d6ef386ba88dcaaf52a3','White Sauce I — Medium Thickness',16,'A medium-thickness milk sauce balances butter and flour for coating vegetables or other cooked foods.'),('historical-4365925d9b1756d9b999c47b','White Sauce II — Thick',24,'A thicker milk sauce contains more flour than the companion thin and medium formulas.')]:
 roux(id,title,28,f,[milk(240)],4,desc,season=[salt(1.5),pepper(.1)],notes='Missing cross-references are expanded to full steps. The three flour levels remain separate formulations; 240 ml milk and weighed spoon ingredients are modern choices.')
