add('historical-69dfcd5ed44ecf04cc14ca53','Salsa Blanca (Water-Based Sauce with Yolk)',6,20,'A flour-thickened water sauce is enriched with rendered beef fat and an egg-yolk liaison.',[flour(20),water(300),water(30,'liaison'),ing('fat',56,'g','food-grade rendered beef fat','Use 56 g unsalted butter for a dairy-containing variation, or refined vegetable oil for a different flavor.'),salt(1.5),pepper(),yolk()],['Whisk {{flour}} into {{water}} in a saucepan until smooth. Bring to a gentle simmer, stirring continuously, and cook 10 minutes over low heat.','Remove from the heat and whisk in {{fat}}, {{salt}} and {{pepper}} until incorporated.','Whisk {{yolk}} with {{liaison}} in a bowl. Gradually whisk a few spoonfuls of warm sauce into the yolk mixture, then return it to the saucepan.','Stir over low heat until the sauce reaches 71°C (160°F), without boiling. Serve immediately.'],'The original flour slurry and fat-at-the-end method are retained. Water amounts are supplied and the yolk liaison is now cooked.')
add('historical-f5ac77b47b9f5a4315904526','Salsa Bianca (Butter Sauce with Vinegar and Yolk)',6,20,'A lightly browned flour base is enriched with butter, vinegar and egg yolk, giving a rich tangy sauce.',[butter(100),flour(8),stock(200),vinegar(15),yolk(),salt(1),pepper()],['Melt {{butter|0.5}} in a saucepan. Stir in {{flour}} and cook over medium-low heat for about 3 minutes until pale golden, not dark.','Gradually whisk in {{stock}} and simmer gently for 5 minutes until smooth.','Remove from the heat and whisk in the remaining {{butter|0.5}}, {{vinegar}}, {{salt}} and {{pepper}}.','Whisk {{yolk}} in a bowl. Gradually add a few spoonfuls of warm sauce, then return everything to the pan. Stir over low heat to 71°C (160°F), without boiling. Serve immediately.'],'The source’s divided butter, pale-brown roux and vinegar remain. Stock and spoon quantities are supplied, and the yolk receives a controlled final heating.')
r=add('historical-3bcdeb5bd770d3bb386bbc32','Smält Smör (Melted Butter with Lemon)',6,5,'Gently melted butter receives a little lemon juice and salt for a simple finishing sauce.',[butter(120),lemon(1.25),salt(2)],['Melt {{butter}} gently in a small saucepan just before serving, keeping it pale.','Remove from the heat and stir in {{lemon}} and {{salt}}. Spoon over a separately prepared dish and serve immediately.'],'The source gram quantities are retained. The quarter-teaspoon lemon is assigned 1.25 ml. The browned-butter option is retained separately; parsley belongs to the serving dish, not this sauce.')
r['variants']=[{'id':'browned','label':'Browned butter finish','ingredients':copy.deepcopy(r['ingredients']),'steps':['Melt {{butter}} in a light-colored saucepan over medium-low heat. Stir as it foams, then watch closely until the milk solids turn golden brown and smell nutty, about 3–5 minutes.','Remove from the heat immediately and pour into a heatproof bowl to stop browning. Let the bubbling subside, then carefully stir in {{lemon}} and {{salt}}. Serve at once.']}]
for old,new in merges.items():
 aliases[old]={'id':old,'canonicalId':new,'bodySha256':original(old)['bodySha256'],'reason':'Full ingredient quantities and complete methods reviewed together: equivalent sauce formulation; all source credits retained. Meaningful cream, mesost or egg-lemon finishes remain named variations rather than separate copies.'}
aliases['historical-9eb68b012c5fd0bcb97282c3']['reason']='The source water-bath and direct-heat versions converge on the same modern measured saucepan formula. Both full ingredient/method sources were reviewed and both credits retained; modern method changes are disclosed.'
(root/'content-overrides.json').write_text(json.dumps(list(records.values()),ensure_ascii=False,indent=2),encoding='utf-8')
(root/'recipe-aliases.json').write_text(json.dumps(list(aliases.values()),ensure_ascii=False,indent=2),encoding='utf-8')
assert len(newids)==26 and len(set(newids))==26
for id in newids:
 r=records[id];db.execute('insert or replace into decisions values(?,?,?,?,?)',(id,r['bodySha256'],'prepared-adaptation','Full sauce formula and method reviewed; measured modern adaptation with explicit choices','repair-batch-004.py'))
for old in merges:
 r=aliases[old];db.execute('insert or replace into decisions values(?,?,?,?,?)',(old,r['bodySha256'],'prepared-merge',r['reason'],'repair-batch-004.py'))
db.commit()
print(json.dumps({'newAdaptations':len(newids),'newMergedSources':len(merges),'totalOverrides':len(records),'totalAliases':len(aliases)}))
